def perm_heap(a):
    def heap(k):
        if k==1:
            out.append(a.copy())
        else:
            for i in range(k):
                heap(k-1)
                a[0],a[k-1] = a[k-1],a[0] if k%2 else a[i],a[k-1]
    out=[]; heap(len(a)); return out

def perm_rec(lst):
    if len(lst)<=1: return [lst]
    res=[]
    for i in range(len(lst)):
        for p in perm_rec(lst[:i]+lst[i+1:]):
            res.append([lst[i]]+p)
    return res

def perm_backtrack(a):
    out=[]
    def bt(i):
        if i==len(a): out.append(a.copy())
        else:
            for j in range(i,len(a)):
                a[i],a[j]=a[j],a[i]; bt(i+1); a[i],a[j]=a[j],a[i]
    bt(0); return out

def perm_string(s):
    if len(s)<=1: return [s]
    out=[]
    for i,ch in enumerate(s):
        for tail in perm_string(s[:i]+s[i+1:]):
            out.append(ch+tail)
    return out

def nested_power(choices, m):
    def rec(d, cur):
        if d == m:
            res.append(cur)
        else:
            for o in choices:
                rec(d+1, cur + [o])
    res=[]; rec(0, []); return res

def cartesian_m(arrays):
    def rec(i):
        if i==len(arrays): return [[]]
        out=[]
        for x in arrays[i]:
            for tail in rec(i+1): out.append([x]+tail)
        return out
    return rec(0)

def m_dim_sum(arrays):
    total=0
    def rec(i, cur):
        nonlocal total
        if i==len(arrays): total+=sum(cur)
        else:
            for x in arrays[i]: rec(i+1, cur+[x])
    rec(0, []); return total

def m_dim_prod(arrays):
    out=[]
    def rec(i, cur):
        if i==len(arrays): out.append(cur)
        else:
            for x in arrays[i]: rec(i+1, cur+[x])
    rec(0, []); return out

def m_level_paths(n, m):
    def rec(d, s):
        if d==m: return [s]
        out=[]
        for i in range(n): out+=rec(d+1, s+str(i))
        return out
    return rec(0, '')

def build_strings(chars, m):
    def rec(i):
        if i==m: return ['']
        out=[]
        for c in chars:
            for s in rec(i+1): out.append(c+s)
        return out
    return rec(0)

def nested_lists(arr, m):
    def rec(d):
        if d==m: return [[]]
        out=[]
        for x in arr:
            for tail in rec(d+1): out.append([x]+tail)
        return out
    return rec(0)

def power_combinations(options, depth):
    def rec(d, cur):
        if d == depth:
            combos.append(cur)
        else:
            for o in options:
                rec(d+1, cur + [o])
    combos=[]; rec(0, []); return combos

def option_sequences(elements, k):
    if k == 0: return [[]]
    res=[]
    for e in elements:
        for seq in option_sequences(elements, k-1):
            res.append([e]+seq)
    return res

def hanoi_moves(n, a, b, c):
    if n>0:
        hanoi_moves(n-1, a, c, b)
        hanoi_moves(n-1, b, a, c)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

