def log_base_n(x, base):
    count = 0
    while x >= base:
        x //= base
        count += 1
    return count

def sort_and_count(arr):
    def ms(a):
        if len(a) <= 1: return a, 0
        m = len(a)//2
        L, ci = ms(a[:m]); R, cj = ms(a[m:])
        i = j = inv = 0; merged=[]
        while i < len(L) and j < len(R):
            if L[i] <= R[j]: merged.append(L[i]); i+=1
            else: merged.append(R[j]); j+=1; inv += len(L)-i
        return merged+L[i:]+R[j:], ci+cj+inv
    return ms(arr)

def bst_sort(lst):
    class Node:
        def __init__(self,v): self.v, self.l, self.r = v, None, None
        def insert(self,x):
            if x < self.v:
                if self.l: self.l.insert(x)
                else: self.l = Node(x)
            else:
                if self.r: self.r.insert(x)
                else: self.r = Node(x)
        def inorder(self):
            return (self.l.inorder() if self.l else []) + [self.v] + (self.r.inorder() if self.r else [])
    it = iter(lst)
    root = Node(next(it, None))
    for x in it: root.insert(x)
    return root.inorder()
